CREATE PROCEDURE "DP_MULTIPLE_FORECAST_TES" (IN TBL_NAME NVARCHAR(100), IN CONTROLTBL_NAME NVARCHAR(100), OUT RESULT TABLE (GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER   AS  BEGIN     DECLARE MULTIPLEFORECAST_CONTROLTBL TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "INTARGS" INT, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR(100));     DECLARE MULTIPLEFORECAST_OUTPARAMETER0  TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE MULTIPLEFORECAST_RESULT0  TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE MULTIPLEFORECAST_OUTPARAMETER1  TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE MULTIPLEFORECAST_RESULT1  TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE DATA_TABLE TABLE(GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE);     DECLARE ROWCNT INT;     DECLARE DIFF INT;     DECLARE ROWINDEX INT;     DECLARE GROUPCNT INT;     DECLARE GROUPID VARCHAR (100);          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#SOURCEDATAHD73Y4GFKV093JDU' ;     IF ROWCNT>0 THEN     DROP TABLE #SOURCEDATAHD73Y4GFKV093JDU;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #SOURCEDATAHD73Y4GFKV093JDU (GROUPID VARCHAR (100),TIMESTAMP INT,VALUE DOUBLE);     EXECUTE IMMEDIATE 'INSERT INTO #SOURCEDATAHD73Y4GFKV093JDU SELECT * FROM '||:TBL_NAME;     DATA_TABLE=SELECT * FROM #SOURCEDATAHD73Y4GFKV093JDU;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#FORECNTRSHUD93RF';     IF ROWCNT>0 THEN     DROP TABLE #FORECNTRSHUD93RF;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #FORECNTRSHUD93RF ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "INTARGS" INT, "DOUBLEARGS" DOUBLE,"STRINGARGS" VARCHAR(100));     EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF SELECT * FROM '||:CONTROLTBL_NAME;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPGROUPID';     IF ROWCNT>0 THEN         DROP TABLE #TEMPGROUPID;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPGROUPID ("GROUPID" VARCHAR (100));     INSERT INTO #TEMPGROUPID SELECT DISTINCT(GROUPID) as GROUPID FROM :DATA_TABLE;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPUTRESULT';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPUTRESULT;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPUTRESULT ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE);          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPARAMETER';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPARAMETER;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPARAMETER ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));          SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF VALUES (''' || :GROUPID || ''',''SEASONAL'',0, NULL, NULL)';         EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF VALUES (''' || :GROUPID || ''',''SEASONAL'',1, NULL, NULL)';     END FOR;          MULTIPLEFORECAST_CONTROLTBL=SELECT * FROM #FORECNTRSHUD93RF WHERE NAME<>'SEASONAL' UNION ALL SELECT * FROM #FORECNTRSHUD93RF WHERE NAME='SEASONAL'AND INTARGS=0;      CALL PALMULTIPLEFORECASTSMOOTHING_PROC( :DATA_TABLE, :MULTIPLEFORECAST_CONTROLTBL, :MULTIPLEFORECAST_OUTPARAMETER0, :MULTIPLEFORECAST_RESULT0) ;          MULTIPLEFORECAST_CONTROLTBL=SELECT * FROM #FORECNTRSHUD93RF WHERE NAME<>'SEASONAL' UNION ALL SELECT * FROM #FORECNTRSHUD93RF WHERE NAME='SEASONAL'AND INTARGS=1;     CALL PALMULTIPLEFORECASTSMOOTHING_PROC( :DATA_TABLE, :MULTIPLEFORECAST_CONTROLTBL, :MULTIPLEFORECAST_OUTPARAMETER1, :MULTIPLEFORECAST_RESULT1) ;      SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          SELECT COUNT(*) INTO GROUPCNT FROM :DATA_TABLE WHERE GROUPID=:GROUPID;         SELECT (out0.VALUE-out1.VALUE) INTO DIFF FROM :MULTIPLEFORECAST_OUTPARAMETER0 out0 JOIN :MULTIPLEFORECAST_OUTPARAMETER1 out1 ON out0.NAME=out1.NAME          WHERE out0.NAME='MSE' AND out0.GROUPID =:GROUPID AND out1.GROUPID =:GROUPID;         IF DIFF<=0 THEN             INSERT INTO #TEMPOUTPUTRESULT SELECT "GROUPID", "TIMESTAMP",CASE WHEN "VALUE"<0 THEN 0 ELSE "VALUE" END AS "VALUE"  FROM :MULTIPLEFORECAST_RESULT0 WHERE GROUPID=:GROUPID AND TIMESTAMP>:GROUPCNT;             INSERT INTO #TEMPOUTPARAMETER SELECT * FROM :MULTIPLEFORECAST_OUTPARAMETER0 WHERE GROUPID=:GROUPID;         ELSE              INSERT INTO #TEMPOUTPUTRESULT SELECT "GROUPID", "TIMESTAMP",CASE WHEN "VALUE"<0 THEN 0 ELSE "VALUE" END AS "VALUE"  FROM :MULTIPLEFORECAST_RESULT1 WHERE GROUPID=:GROUPID AND TIMESTAMP>:GROUPCNT;             INSERT INTO #TEMPOUTPARAMETER SELECT * FROM :MULTIPLEFORECAST_OUTPARAMETER1 WHERE GROUPID=:GROUPID;         END IF;     END FOR;      RESULT=SELECT * FROM #TEMPOUTPUTRESULT;     SELECT * FROM #TEMPOUTPARAMETER; END
